import { t } from './i18n.js';
import { ACTIVITY_WORDS } from './minduck-activity.js';

export function previewActions(pack, words = []) {
  const supported = new Set(words);
  const declared = new Set((pack?.vocab ?? []).map(entry => entry.id));
  const actions = [{ id: 'auto', type: 'auto', label: t('dress.previewAuto') }];
  for (const word of ['neutral', 'walk', 'write']) {
    if (declared.has(word) && supported.has(word)) {
      actions.push({ id: `word:${word}`, type: 'word', word, label: t(`dress.previewWord.${word}`) });
    }
  }
  for (const [kind, word] of Object.entries(ACTIVITY_WORDS)) {
    if (supported.has(word)) {
      actions.push({ id: `task:${kind}`, type: 'task', kind, label: t(`dress.previewTask.${kind}`) });
    }
  }
  return actions;
}

export function createPreviewPlayer(body, action) {
  let started = false;
  body.set({ roam: action.type === 'auto' ? 'calm' : 'off' });
  return {
    step(dt) {
      if (started || action.type === 'auto' || !(dt > 0 && Number.isFinite(dt))) return;
      if (action.type === 'word') body.do(action.word);
      if (action.type === 'task') body.set({ matterActivity: {
        kind: action.kind, id: `preview-${action.kind}`, expiresAt: Date.now() + 86400000 } });
      started = true;
    },
  };
}

/** Built-in thumbnails are captured from the real figure renderer; imported packs retain their own image. */
export function previewThumbnail(pack, action) {
  if (['minduck-duck', 'minduck-suit-duck'].includes(pack.id)) {
    const id = action.type === 'auto' ? 'word:neutral' : action.id;
    return `${pack.base}previews/${id.replace(':', '-')}.png`;
  }
  return pack.thumb ? pack.base + pack.thumb : null;
}
